import os, rasterio, matplotlib.pyplot as plt, numpy as np; base_path = os.path.expanduser("~\\Desktop\\ssl-multi-peril-resilience-workflow"); s2_path = os.path.join(base_path, "Phase1_Data_Acquisition", "Sentinel2_Optical.tif"); out_path = os.path.join(base_path, "Phase4_Deliverables", "Hazard_Map_Final.png"); src = rasterio.open(s2_path); img = src.read([1, 2, 3]).astype(np.float32); p98 = np.percentile(img, 98) if img.size > 0 else 1.0; img_norm = np.clip(img / p98, 0, 1); plt.imshow(np.transpose(img_norm, (1, 2, 0))); plt.title("Real Sentinel-2 Imagery"); plt.savefig(out_path, dpi=300, bbox_inches="tight"); print("Map generated successfully at:", out_path)
